use serde_json::{json,Value};
use std::io::{self,BufRead};
fn main(){let line=io::stdin().lock().lines().next().transpose().unwrap().unwrap_or_default();let request:Value=match serde_json::from_str(&line){Ok(v)=>v,Err(e)=>{println!("{}",json!({"jsonrpc":"2.0","id":null,"error":{"code":-32700,"message":e.to_string()}}));return}};let id=request.get("id").cloned().unwrap_or(Value::Null);if request.get("protocol").and_then(Value::as_u64)!=Some(1){println!("{}",json!({"jsonrpc":"2.0","id":id,"error":{"code":-32600,"message":"unsupported protocol"}}));return}match request.get("method").and_then(Value::as_str){Some("status")=>println!("{}",json!({"jsonrpc":"2.0","id":id,"result":{"healthy":true,"message":"hello from Rust"}})),_=>println!("{}",json!({"jsonrpc":"2.0","id":id,"error":{"code":-32601,"message":"method not found"}}))}}
